export type UserFacingFailure = "actionable" | "closed" | "pending";

/**
 * Whose move a failed application is on.
 *
 * - `candidate` — there is a form to open or an answer to give.
 * - `us` — a wall, our bug, or a report nobody could classify; the fix is a
 *   deploy, not a click.
 * - `nobody` — the posting is gone; nothing to do, nothing to worry about.
