export type WaitingOn = "candidate" | "us" | "nobody";

/** What a failed application looks like to the reader, and whose move it is. */
export interface FailurePresentation {
  kind: UserFacingFailure;
  waitingOn: WaitingOn;
}

/** Which of the three a classified failure belongs to, and whose move it is. */
export function userFacingFailure(outcome: FailureOutcome): FailurePresentation {
  switch (outcome) {
    case "needs_login":
    case "needs_answer":
      return { kind: "actionable", waitingOn: "candidate" };
    case "posting_gone":
      return { kind: "closed", waitingOn: "nobody" };
    case "wall":
    case "our_bug":
    case "unknown":
      return { kind: "pending", waitingOn: "us" };
  }
}
```

